const body = $input.first().json.body || $input.first().json;
const name = body.name || body.customer_name || 'Cliente';
const email = body.email || body.customer_email || '';
const daysValid = Number(body.days || body.plan_days || 30);
const randomNum = Math.floor(1000 + Math.random() * 9000);
const cleanName = (name.split(' ')[0] || 'vip').toLowerCase().replace(/[^a-z0-9]/g, '');
const username = body.username || `${cleanName}_${randomNum}`;
const password = body.password || `play_${Math.random().toString(36).substring(2, 8)}`;

return [{ json: { name, email, username, password, daysValid, phone: body.phone || body.customer_phone || '' } }];

const res = $input.first().json;
const creds = res.loginCredentials || {};
const user = res.user || {};
const expiryDate = user.expiresAt ? new Date(user.expiresAt).toLocaleDateString('pt-BR') : '—';

const whatsappMessage = `🌟 *Seu Acesso ao JstudioPlay Está Liberado!*
━━━━━━━━━━━━━━━━
Olá, *${user.name}*!

🌐 *Acesso:* ${creds.loginUrl}
👤 *Usuário:* \`${creds.username}\`
🔑 *Senha:* \`${creds.password}\`
📅 *Válido até:* ${expiryDate} (${user.daysValid} dias)
━━━━━━━━━━━━━━━━
_Bom entretenimento!_`;

return [{ json: { success: true, user, loginCredentials: creds, formattedMessage: whatsappMessage } }];
